code_units=['What is coding?','Step by step','Find the bug','Repeat it','If this, then that','Meet JavaScript','Boxes called variables','Math with code','Make it happen','Little coder projects']
ai_units=['What is AI?','Learning from examples','Sorting and patterns','AI that sees','AI that listens and talks','AI helpers around us','AI makes mistakes','Be safe with AI','People are in charge','Little AI explorer']
code_activities=['Give a grown-up 3 clear instructions to follow, like stand up, turn around, sit down.','Draw the steps for making a snack. Ask a grown-up to follow them in order.','Ask a grown-up to make a mistake following your steps. Find the bug and fix it.','Make up a dance loop: repeat 3 times: clap, stomp. Teach it to a grown-up.','Play Simon Says with if rules: if I touch my nose, you clap.','With a grown-up, write `console.log("Hello")` on paper. Say what it would show.','Draw 3 boxes. Give each a name and put a number or word inside, like `let pets = 2`.','Make up 2 code math problems like 3 + 1. Solve them with toys.','Draw a button. Decide what happens when it is clicked, then act it out.','Plan a tiny game with a grown-up. List its steps, one loop, and one if rule.']
ai_activities=['Look around your home with a grown-up. Find one thing that uses a computer and one that does not.','Look at 3 pictures of the same animal with a grown-up. Talk about what is the same.','Sort your toys into groups. Tell a grown-up your sorting rule.','Look at a photo with a grown-up. Name 3 things you can spot in it.','Say a short sentence slowly and clearly. Ask a grown-up to say it back.','Ask a grown-up which helpers on their phone use AI. Draw one.','Play a guessing game. Make a silly mistake on purpose and fix it together.','With a grown-up, make two lists: things that are private and things that are okay to share.','Draw AI helping people or nature. Tell a grown-up about your picture.','Play Train the AI: a grown-up shows you examples, then you sort new things.']

for subject,raw,units,activities in [('english',english,eng_units,eng_activities),('science',science,sci_units,sci_activities),('coding',coding,code_units,code_activities),('ai',ai,ai_units,ai_activities)]:
    rows=[r for r in raw.strip().splitlines() if r.strip()];assert len(rows)==50,(subject,len(rows))
    for i,row in enumerate(rows):
        title,learn,*items=row.split('|');assert len(items)==3,title
        questions=[]
        for item in items:
            p,a,w1,w2=item.split('~');questions.append(q(p,a,[w1,w2],learn))
        add(subject,units[i//5],title,learn,questions,activities[i//5])
assert len(DATA)==250
for subject in ['math','english','science','coding','ai']:
    mods=[m for m in DATA if m['subject']==subject]
    for i,m in enumerate(mods):
        if i:
            # Mix recent and earlier skills, preserving each review question's provenance.
            previous=[mods[i-1],mods[max(0,i-5)]]
            m['review']=[dict(p['questions'][(i+k)%3],source=p['title'],sourceId=p['id']) for k,p in enumerate(previous)]
        else:m['review']=[dict(m['questions'][0],source=m['title'],sourceId=m['id']),dict(m['questions'][1],source=m['title'],sourceId=m['id'])]
Path('dist/curriculum.js').write_text('const curriculum = '+json.dumps(DATA,ensure_ascii=False)+';\n',encoding='utf-8')
print(f'Created {len(DATA)} modules, {3*len(DATA)} focus questions, {2*len(DATA)} review questions.')
